'use strict';
const $=id=>document.getElementById(id),canvas=$('arena'),c=canvas.getContext('2d');
const storage={get(k,d=''){try{return localStorage.getItem(k)??d}catch{return d}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
const roster=[
{id:'raiken',name:'RAIKEN',animal:'Lobo',kind:'wolf',color:'#d8ff78',origin:'TOKYO · JAPÓN',title:'El guardián del distrito',power:7,speed:8,guard:6,build:1,hair:0,skin:'#c09b7d',special:'Colmillo lunar',track:'Luna de acero',genre:'Industrial / synth rock',bpm:132,root:45,wave:'sawtooth',notes:[0,7,10,7,3,7,12,10],story:'Raiken creció protegiendo las calles del Distrito Nueve. Cuando su hermano desapareció durante las pruebas del proyecto Génesis, descubrió que su propia sangre escondía el código del lobo. Ahora entra en el torneo clandestino para encontrar el laboratorio que lo inició todo.',goal:'Su instinto le exige vengarse. Su promesa le exige traer a su hermano de vuelta.',ending:'Raiken encuentra a su hermano entre los sujetos retenidos y destruye las celdas. Renuncia a perseguir al director para guiar a los supervivientes a casa. Por primera vez, su manada no se define por la sangre, sino por quienes decide proteger.'},
{id:'vex',name:'VEX',animal:'Tigre',kind:'cat',color:'#ff825e',origin:'BUSAN · COREA',title:'La garra sin dueño',power:9,speed:6,guard:6,build:1.1,hair:1,skin:'#bc8c72',special:'Zarpazo carmesí',track:'Líneas de fuego',genre:'Breakbeat / bass',bpm:146,root:38,wave:'square',notes:[0,0,3,7,6,3,10,7],story:'Vex fue el campeón de una organización que compraba luchadores y vendía sus victorias. Escapó al despertar su forma de tigre, pero dejó atrás a su entrenador. El torneo es su única puerta de regreso a la organización, esta vez por voluntad propia.',goal:'No busca una corona. Busca romper el contrato que mantiene cautivo a su maestro.',ending:'Vex derrota al ejecutor de la organización y transmite sus contratos secretos. Su entrenador recupera la libertad. Juntos convierten el antiguo ring de apuestas en un gimnasio donde nadie vuelve a ser propiedad de nadie.'},
{id:'nyra',name:'NYRA',animal:'Pantera',kind:'cat',color:'#b9a0ff',origin:'NAIROBI · KENIA',title:'La sombra que recuerda',power:6,speed:10,guard:5,build:.88,hair:2,skin:'#765444',special:'Eclipse violeta',track:'Sombra violeta',genre:'Dark garage / ambient',bpm:128,root:49,wave:'sine',notes:[0,3,10,14,12,7,3,2],story:'Nyra era una rastreadora que recuperaba archivos robados. Un encargo la llevó a un centro de Génesis y le costó sus recuerdos. Solo conserva una melodía y una marca en el brazo. Sigue las señales del torneo porque cada rival reconoce una parte de su pasado.',goal:'Recuperar su memoria sin convertirse otra vez en el arma que otros diseñaron.',ending:'Nyra descubre que borró sus recuerdos para proteger la ubicación de un refugio. Recupera el archivo, pero destruye las coordenadas ante las cámaras del torneo. Su pasado ya no la encierra: ahora puede elegir a quién contarlo.'},
{id:'bronn',name:'BRONN',animal:'Oso',kind:'bear',color:'#e7b774',origin:'YUKÓN · CANADÁ',title:'El último refugio',power:10,speed:4,guard:10,build:1.27,hair:3,skin:'#b68b6d',special:'Impacto glaciar',track:'Montaña de hierro',genre:'Doom synth / percusión',bpm:90,root:33,wave:'triangle',notes:[0,0,5,3,0,7,5,2],story:'Bronn dirigía un equipo de rescate en las montañas. Una fuga química despertó su forma de oso mientras salvaba a sus compañeros. Cuando la empresa responsable acusó al equipo del desastre, decidió llevar sus pruebas al único lugar donde sus directivos aparecían: el torneo.',goal:'Limpiar el nombre de sus compañeros y conseguir un tratamiento para los afectados.',ending:'Bronn entrega las pruebas a una red de periodistas y obliga a abrir los almacenes médicos. Vuelve al norte con suministros, no con un trofeo. La vieja estación de rescate se convierte en el primer refugio para personas transformadas.'},
{id:'kaida',name:'KAIDA',animal:'Dragón',kind:'dragon',color:'#ff697e',origin:'CHENGDU · CHINA',title:'La heredera de ceniza',power:9,speed:7,guard:5,build:1.03,hair:4,skin:'#d3a388',special:'Aliento de ceniza',track:'Ceniza imperial',genre:'Electro / arpegios',bpm:140,root:50,wave:'sawtooth',notes:[0,2,7,9,14,9,7,2],story:'Kaida heredó un archivo familiar sobre una mutación imposible: el dragón. Génesis robó el archivo y lo usó para crear soldados inestables. Ella es la única portadora que ha aprendido a controlar el cambio, y cada combate la acerca a quienes copiaron su sangre.',goal:'Recuperar la investigación y decidir si un poder así debe volver a transmitirse.',ending:'Kaida recupera el archivo y elimina las instrucciones para fabricar soldados. Conserva únicamente el tratamiento que estabiliza a los portadores. Su herencia deja de ser una técnica de guerra y se convierte en una oportunidad para vivir.'},
{id:'soren',name:'SOREN',animal:'Halcón',kind:'bird',color:'#81d8ff',origin:'BERGEN · NORUEGA',title:'El mensajero del cielo',power:5,speed:10,guard:6,build:.9,hair:5,skin:'#dec0a0',special:'Caída del firmamento',track:'Cielo de cristal',genre:'Trance / melodía aérea',bpm:138,root:57,wave:'triangle',notes:[0,7,12,16,14,12,7,4],story:'Soren transportaba medicinas entre ciudades aisladas. Descubrió que sus rutas también servían para trasladar sujetos de prueba. Al denunciarlo, perdió su licencia y pasó a ser perseguido. Su forma de halcón le permite seguir volando, pero necesita pruebas para detener los convoyes.',goal:'Ganar acceso al centro de comunicaciones del torneo y revelar las rutas secretas.',ending:'Soren transmite el mapa de los convoyes y coordina una operación de rescate. Rechaza recuperar su antigua licencia bajo las mismas condiciones. Funda una red de mensajeros que transporta ayuda sin preguntar quién puede pagarla.'},
{id:'amara',name:'AMARA',animal:'Serpiente',kind:'snake',color:'#6ee6bd',origin:'MARRAKECH · MARRUECOS',title:'La verdad entre escamas',power:7,speed:9,guard:5,build:.86,hair:6,skin:'#a57552',special:'Espiral esmeralda',track:'Veneno de seda',genre:'Dub / secuencia hipnótica',bpm:112,root:46,wave:'sine',notes:[0,1,4,7,8,7,4,1],story:'Amara investigaba una cura para las mutaciones involuntarias. Su laboratorio fue cerrado cuando se negó a convertirla en un arma. Se aplicó un prototipo para salvar sus notas y despertó una forma serpentina. Ha venido a recuperar las muestras que sus antiguos socios subastan.',goal:'Demostrar que controlar una transformación no exige borrar la identidad de quien la vive.',ending:'Amara recupera las muestras y publica una fórmula de estabilización de acceso libre. Decide mantener su propia transformación. Para ella, curar significa devolver una elección, no obligar a todos a ser iguales.'},
{id:'dante',name:'DANTE',animal:'Toro',kind:'bull',color:'#ffb459',origin:'SEVILLA · ESPAÑA',title:'La fuerza de una promesa',power:10,speed:5,guard:9,build:1.22,hair:7,skin:'#be9278',special:'Embestida solar',track:'Pulso de bronce',genre:'Percusión / techno',bpm:124,root:40,wave:'square',notes:[0,5,0,7,3,5,10,7],story:'Dante era mecánico de la arena y conocía todos sus túneles. Cuando el sistema de seguridad encerró a los trabajadores durante una prueba, derribó las puertas con una fuerza que no sabía que tenía. Ahora los organizadores quieren convertirlo en su nueva atracción.',goal:'Entrar como luchador para abrir una salida segura a quienes aún trabajan bajo amenaza.',ending:'Dante usa el combate final como distracción y abre los túneles de servicio. Sale de la arena junto a los trabajadores y funda un taller colectivo. La fuerza que antes vendían como espectáculo ahora construye algo que les pertenece.'},
{id:'reina',name:'REINA',animal:'Zorro',kind:'fox',color:'#ffadd4',origin:'OSAKA · JAPÓN',title:'La sonrisa del engaño',power:5,speed:10,guard:7,build:.87,hair:8,skin:'#dfb49a',special:'Danza de espejos',track:'Neón travieso',genre:'Future bass / synth pop',bpm:150,root:54,wave:'triangle',notes:[0,4,7,11,12,11,7,9],story:'Reina se infiltraba en eventos de lujo para recuperar bienes robados. En una caja fuerte encontró su propio expediente de nacimiento: había sido criada como sujeto de Génesis. Se inscribe en el torneo con una identidad falsa para conocer a la persona que ordenó liberarla.',goal:'Descubrir quién la salvó y por qué su expediente sigue marcado como activo.',ending:'Reina descubre que una técnica anónima falsificó su muerte para liberarla. Encuentra a la mujer y le entrega los expedientes de otros niños. Esta vez usan el engaño juntas, para sacar del sistema a quienes aún no tienen una salida.'},
{id:'kairo',name:'KAIRO',animal:'Chacal',kind:'wolf',color:'#f0dc8d',origin:'EL CAIRO · EGIPTO',title:'El custodio de las ruinas',power:8,speed:7,guard:8,build:1.04,hair:9,skin:'#956d4d',special:'Juicio del desierto',track:'Arena y circuito',genre:'Electro / escala oriental',bpm:118,root:43,wave:'sawtooth',notes:[0,1,4,5,7,8,11,7],story:'Kairo custodiaba una colección de muestras biológicas antiguas. Los financiadores de Génesis saquearon el depósito y le ofrecieron dinero para guardar silencio. Rechazó el trato, pero quedó expuesto a una muestra que despertó al chacal. Persigue las piezas vendidas en el mercado del torneo.',goal:'Recuperar el archivo y evitar que el patrimonio de su comunidad se convierta en armamento.',ending:'Kairo reúne las muestras y devuelve el archivo a un consejo de investigadores de su comunidad. Su propia transformación queda documentada con su consentimiento. Ningún patrocinador vuelve a decidir a solas qué se estudia y para qué.'},
{id:'mako',name:'MAKO',animal:'Tiburón',kind:'shark',color:'#72b9f5',origin:'CALLAO · PERÚ',title:'La corriente indomable',power:9,speed:7,guard:7,build:1.13,hair:10,skin:'#ac8062',special:'Marea abisal',track:'Marea profunda',genre:'Drum and bass / sub',bpm:170,root:35,wave:'sine',notes:[0,7,3,10,0,12,10,7],story:'Mako buceaba reparando cascos en el puerto del Callao. Encontró un contenedor con sujetos de prueba que iban a ser transportados fuera del país. Al abrirlo quedó expuesto al compuesto Génesis. Su nueva forma de tiburón lo mantiene vivo, pero la naviera lo ha convertido en fugitivo.',goal:'Llegar al promotor del torneo, dueño de la naviera, y encontrar a los desaparecidos del puerto.',ending:'Mako obtiene los registros de embarque y libera a los cautivos antes de que zarpe el último barco. Regresa al Callao y organiza una red de vigilancia con los trabajadores del puerto. Ya nadie desaparece entre contenedores sin que alguien lo vea.'},
{id:'onyx',name:'ONYX',animal:'Cuervo',kind:'bird',color:'#c5b7e8',origin:'PRAGA · CHEQUIA',title:'El eco del origen',power:8,speed:8,guard:6,build:.98,hair:11,skin:'#b6a29a',special:'Réquiem del vacío',track:'Réquiem de silicio',genre:'Gótico / synth oscuro',bpm:104,root:42,wave:'triangle',notes:[0,3,6,11,12,6,3,11],story:'Onyx fue el archivista de Génesis. Durante años creyó que las pruebas eran voluntarias, hasta encontrar grabaciones que demostraban lo contrario. Copió los archivos dentro de su implante y huyó. Cada transformación en cuervo daña una parte de ese archivo, así que el tiempo se le termina.',goal:'Sobrevivir al torneo y entregar la verdad antes de que su memoria digital desaparezca.',ending:'Onyx transmite el archivo completo durante la final y acepta declarar sobre su participación. Pierde el implante, pero conserva sus recuerdos humanos. No se proclama inocente: comienza a reparar el daño ayudando a identificar a cada víctima.'}
];
let selected=0,opponent=1,storyMode=false,chapter=0,storyRoute=[],storyWon=false,musicTimer=null,musicStep=0,musicNext=0,musicBus=null,musicIndex=-1;
function portraitSVG(d){const ears=d.kind==='bull'?'<path d="M42 55 Q12 20 29 12 L50 47 M78 55 Q108 20 91 12 L70 47" fill="none" stroke="currentColor" stroke-width="7"/>':d.kind==='bird'?'<path d="M20 135 L1 68 35 89 10 37 50 66 M100 135 L119 68 85 89 110 37 70 66" fill="currentColor" opacity=".45"/>':d.kind==='shark'?'<path d="M29 120 L4 38 48 80" fill="currentColor"/>':d.kind==='snake'?'<path d="M39 45 Q-7 60 23 115 L60 95 98 115 Q125 60 81 45" fill="currentColor" opacity=".45"/>':d.kind==='bear'?'<circle cx="38" cy="44" r="14" fill="currentColor"/><circle cx="82" cy="44" r="14" fill="currentColor"/>':'<path d="M35 58 L24 12 53 40 69 40 96 12 85 62" fill="currentColor"/>';return `<svg viewBox="0 0 120 150" aria-hidden="true" style="color:${d.color}"><path d="M9 150 L18 110 44 92 77 92 102 110 113 150" fill="#283641"/>${ears}<path d="M39 94 L60 112 81 94 93 121 72 145 47 145 25 121" fill="currentColor" opacity=".8"/><path d="M35 47 L60 32 85 47 88 79 74 101 46 101 32 79" fill="${d.skin}"/><path d="M32 57 L35 31 58 ${17+d.hair%4*4} 83 31 91 61 73 48 58 37 42 58" fill="#111722"/><path d="M35 67 L59 74 84 65 81 81 60 87 39 81" fill="currentColor"/><path d="M41 73 L53 77 M66 77 L78 72" stroke="#101923" stroke-width="4"/><path d="M44 91 L60 96 76 89 69 104 51 104" fill="#17212b"/><path d="M25 128 L37 137 M84 137 L96 126" stroke="currentColor" stroke-width="3"/></svg>`}
function renderRoster(){const grid=$('roster');grid.innerHTML='';roster.forEach((d,i)=>{const b=document.createElement('button');b.className='fighter-card';b.style.setProperty('--fighter',d.color);b.style.setProperty('--wash',d.color+'30');b.setAttribute('aria-label',d.name+' · '+d.animal);b.setAttribute('aria-pressed',String(i===selected));b.innerHTML=portraitSVG(d)+`<small>${String(i+1).padStart(2,'0')}</small><strong>${d.name}</strong><span>${d.animal.toUpperCase()}</span>`;b.onclick=()=>choose(i);grid.appendChild(b)});$('opponent').innerHTML=roster.map((d,i)=>`<option value="${i}">${d.name} · ${d.animal}</option>`).join('');choose(selected)}
function choose(i){selected=i;storage.set('rift.character',roster[i].id);const d=roster[i];$('selection').style.setProperty('--accent',d.color);[...$('roster').children].forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));$('char-number').textContent='SUJETO '+String(i+1).padStart(2,'0');$('char-origin').textContent=d.origin;$('portrait').innerHTML=portraitSVG(d);$('char-animal').textContent='FORMA BESTIAL / '+d.animal.toUpperCase();$('char-name').textContent=d.name;$('char-title').textContent=d.title;$('char-story').innerHTML='<p>'+d.story+'</p><p><strong>Objetivo:</strong> '+d.goal+'</p>';$('char-style').innerHTML=`<p><strong>${d.special}:</strong> ataque especial de alcance extendido (L), consume 100 de energía.</p><p>Su velocidad y potencia ${d.speed>=9?'favorecen acercamientos rápidos':d.power>=9?'premian golpes contundentes':'permiten un estilo equilibrado'}. La defensa reduce el daño recibido. Pulsa B con la barra de instinto llena para transformarte durante 8 segundos: +25 % de daño y +15 % de velocidad.</p>`;$('stats').innerHTML=[['PODER',d.power],['VELOCIDAD',d.speed],['DEFENSA',d.guard]].map(([label,v])=>`<div>${label}<b>${v}</b><i><em style="width:${v*10}%"></em></i></div>`).join('');$('track-name').textContent=d.track;$('track-style').textContent=d.genre+' · '+d.bpm+' BPM';if(Number($('opponent').value)===selected)$('opponent').value=String((i+1)%12);opponent=Number($('opponent').value);p=fighter(740,d.color,1,d);if(!muted)startMusic(i);updatePreviewButton()}
function showSelection(){state='select';$('lobby').hidden=true;$('selection').hidden=false;$('hud').hidden=true;$('controls').hidden=true;$('touch').hidden=true;$('modal').hidden=true;$('pause').hidden=true;$('logout').hidden=false;$('announce').textContent='';document.body.classList.remove('playing');document.body.classList.add('selecting');keys={};choose(selected);if(!muted)startMusic(selected)}
function updatePreviewButton(){$('preview-track').textContent=muted?'▶ ESCUCHAR':'Ⅱ SILENCIAR';$('sound').textContent='SONIDO '+(muted?'OFF':'ON');$('now-playing').hidden=muted}
async function enableMusic(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();muted=false;startMusic(selected)}catch{muted=true;$('preview-track').textContent='AUDIO NO DISPONIBLE'}updatePreviewButton()}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null;if(musicBus){musicBus.gain.setTargetAtTime(0,audio.currentTime,.025);const old=musicBus;setTimeout(()=>old.disconnect(),200);musicBus=null}musicIndex=-1}
function tone(freq,t,duration,type,volume,slide=false){if(!musicBus)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(slide)o.frequency.exponentialRampToValueAtTime(35,t+duration);g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(volume,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(musicBus);o.start(t);o.stop(t+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
function startMusic(index){if(muted||!audio||document.hidden||state==='paused')return;if(musicIndex===index&&musicTimer)return;stopMusic();musicIndex=index;musicBus=audio.createGain();musicBus.gain.value=Number($('volume').value)/100*.48;musicBus.connect(audio.destination);musicStep=0;musicNext=audio.currentTime+.05;$('playing-name').textContent=roster[index].name+' / '+roster[index].track;$('now-playing').hidden=false;const schedule=()=>{const d=roster[index],beat=60/d.bpm/2;if(musicNext<audio.currentTime-.2)musicNext=audio.currentTime+.02;while(musicNext<audio.currentTime+.15){const n=musicStep%16,midi=d.root+d.notes[musicStep%8]+12;const hz=m=>440*2**((m-69)/12);tone(hz(midi),musicNext,beat*.72,d.wave,.11);if(n%2===0)tone(hz(d.root+(n>=8?d.notes[2]:0)-12),musicNext,beat*1.7,'triangle',.24);if(n%4===0)tone(140,musicNext,.15,'sine',.55,true);if(n%4===2){tone(165,musicNext,.07,'triangle',.15);tone(1600,musicNext,.045,'square',.025)}tone(n%2?4200:6300,musicNext,.024,'square',.012);if(n===0)for(const note of [0,7,12])tone(hz(d.root+note),musicNext,beat*7,'sine',.035);musicNext+=beat;musicStep++}};schedule();musicTimer=setInterval(schedule,50)}
function toggleMusic(){if(muted)enableMusic();else{muted=true;stopMusic();updatePreviewButton()}}
function transform(f){if(state!=='fight'||f.rage<100||f.beast>0||f.stun>0)return;f.rage=0;f.beast=8;shake=15;sound(330,.45);for(let i=0;i<45;i++)particles.push({x:f.x,y:540,vx:(Math.random()-.5)*700,vy:(Math.random()-.5)*650,life:.7,color:f.color})}
function beginSelected(){storyMode=$('mode').value==='story';opponent=Number($('opponent').value);chapter=0;storyRoute=[(selected+3)%12,(selected+7)%12,(selected+11)%12];if(storyMode){opponent=storyRoute[0];storyIntro()}else start()}
function storyIntro(){state='storyintro';$('selection').hidden=true;document.body.classList.remove('selecting');$('modal').hidden=false;$('result-label').textContent='HISTORIA / '+roster[selected].name+' / CAPÍTULO '+(chapter+1)+' DE 3';$('result-title').textContent=['La invitación.','Tras la máscara.','El núcleo Génesis.'][chapter];$('result-copy').textContent=chapter===0?roster[selected].story+' '+roster[selected].goal:chapter===1?'El primer rival entrega una clave del archivo Génesis. '+roster[selected].name+' avanza hacia el laboratorio, pero '+roster[opponent].name+' custodia el siguiente acceso. Ambos persiguen una verdad que la organización ha intentado esconder.':'El archivo está al alcance. '+roster[opponent].name+' exige un último combate para decidir quién llevará las pruebas fuera de la arena. '+roster[selected].goal;$('resume').textContent='COMBATIR CONTRA '+roster[opponent].name+' →';$('modal').querySelector('.result').classList.add('story-result')}
function advanceResult(){if(state==='storyintro'){start();return}if(state==='over'){if(storyMode&&storyWon&&chapter<2){chapter++;opponent=storyRoute[chapter];storyIntro()}else if(storyMode&&storyWon){showSelection()}else start()}else pause()}
function beastFeatures(f,hand){const d=f.data,k=d.kind,color=d.color;c.shadowColor=color;c.shadowBlur=13;if(k==='bird'){poly([[-20,-174],[-105,-235],[-89,-171],[-121,-190],[-92,-133],[-48,-114]],color+'a0');poly([[20,-174],[88,-225],[75,-167],[108,-181],[72,-122],[35,-111]],color+'70')}if(k==='dragon'){poly([[-25,-171],[-110,-232],[-86,-134],[-58,-155],[-39,-110]],color+'90');poly([[-17,-225],[-39,-265],[-4,-236]],color);poly([[12,-232],[35,-267],[29,-215]],color)}if(k==='shark')poly([[-23,-175],[-78,-230],[-55,-115],[-25,-105]],color);if(k==='snake')poly([[-24,-209],[-65,-227],[-67,-164],[-33,-140],[26,-140],[62,-174],[54,-229],[18,-208]],color+'75');if(k==='bear'){ellipse(-22,-236,17,16,color);ellipse(19,-237,17,16,color)}if(['wolf','fox','cat'].includes(k)){poly([[-25,-217],[-35,-269],[-3,-237]],color);poly([[8,-236],[39,-266],[28,-213]],color)}if(k==='bull')line([[-23,-222],[-44,-249],[-40,-271]],'#e8e2c9',9),line([[15,-230],[39,-249],[37,-273]],'#e8e2c9',9);poly([[-25,-222],[8,-235],[31,-212],[40,-196],[18,-180],[-15,-186],[-29,-204]],color);poly([[9,-209],[44,-201],[35,-188],[9,-189]],'#18242d');if(k==='bird')poly([[19,-212],[53,-199],[19,-191]],'#e1c998');line([[-13,-211],[3,-207]],'#fff',4);line([[12,-211],[26,-215]],'#fff',4);for(let i=0;i<3;i++)line([[hand[0]+7,hand[1]-8+i*7],[hand[0]+31,hand[1]-13+i*8]],'#e9f4e0',3);if(['cat','fox','wolf','dragon'].includes(k))line([[-20,-94],[-65,-72],[-89,-112],[-92,-137]],color,12);if(d.animal==='Tigre')for(let y=-175;y<-105;y+=18)line([[-25,y],[0,y+9],[22,y-3]],'#101820',5);if(d.animal==='Chacal')line([[-21,-185],[-31,-150],[-6,-129],[19,-151]],'#f4de81',5);c.shadowBlur=0}

let name=storage.get('rift.name',storage.get('apex.pilot')),state='login',keys={},p,e,round=1,wins=[0,0],time=60,transition=0,particles=[],shake=0,last=0,clock=0,ai=0,muted=true,audio;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function fighter(x,color,face,data=roster[0]){return{x,y:0,vy:0,hp:100,energy:0,rage:100,beast:0,data,color,face,attack:null,cool:0,stun:0,block:false,walk:0}}
function resetRound(){p=fighter(410,roster[selected].color,1,roster[selected]);e=fighter(870,roster[opponent].color,-1,roster[opponent]);time=60;transition=2;state='countdown';particles=[];ai=.6;keys={}}
function record(){return Number(storage.get('rift.wins.'+name.toLowerCase(),'0'))||0}
function lobby(){$('selection').hidden=true;document.body.classList.remove('selecting');stopMusic();$('now-playing').hidden=true;state=name?'ready':'login';$('lobby').hidden=false;$('hud').hidden=true;$('controls').hidden=true;$('touch').hidden=true;$('modal').hidden=true;$('announce').textContent='';$('pause').hidden=true;$('logout').hidden=!name;$('login-panel').hidden=!!name;$('ready-panel').hidden=!name;document.body.classList.remove('playing');$('username').textContent=name;$('record').textContent=record()+' victorias guardadas · Mejor de 3 rounds';keys={};p=fighter(740,'#d8ff78',1);e=fighter(1040,'#ff725c',-1)}
$('login').onsubmit=ev=>{ev.preventDefault();const n=$('name').value.trim();if(n.length<2){$('name').setCustomValidity('Escribe al menos 2 caracteres.');$('name').reportValidity();return}name=n;storage.set('rift.name',name);lobby()};$('name').oninput=()=> $('name').setCustomValidity('');$('logout').onclick=()=>{name='';storage.set('rift.name','');storage.set('apex.pilot','');lobby()};
function start(){$('selection').hidden=true;document.body.classList.remove('selecting');$('modal').querySelector('.result').classList.remove('story-result');wins=[0,0];round=1;resetRound();$('lobby').hidden=true;$('modal').hidden=true;$('hud').hidden=false;$('controls').hidden=false;$('touch').hidden=false;$('pause').hidden=false;$('logout').hidden=true;$('player-name').textContent=roster[selected].name;$('player-type').textContent=name.toUpperCase()+' / '+roster[selected].animal;$('enemy-name').textContent=roster[opponent].name;$('enemy-type').textContent='CPU / '+roster[opponent].animal;document.body.classList.add('playing');sound(100,.16);if(!muted)startMusic(selected)}$('start').onclick=showSelection;
function pause(){if(state==='paused'){state=resumeState;$('modal').hidden=true;if(!muted)startMusic(selected);return}if(!['fight','countdown','roundover'].includes(state))return;resumeState=state;state='paused';stopMusic();keys={};$('modal').hidden=false;$('result-label').textContent='COMBATE EN PAUSA';$('result-title').textContent='Toma aire.';$('result-copy').textContent='Vuelve cuando estés listo. Tu rival puede esperar.';$('resume').textContent='CONTINUAR →'}let resumeState='fight';$('pause').onclick=pause;$('resume').onclick=advanceResult;$('menu').onclick=showSelection;
$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('full').textContent='USA F11'}};
$('sound').onclick=toggleMusic;
function sound(freq,duration){if(muted||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(35,audio.currentTime+duration);g.gain.setValueAtTime(.14,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function attack(f,type){if(state!=='fight'||f.cool>0||f.stun>0||f.block)return;if(type==='special'&&f.energy<100)return;if(type==='special')f.energy=0;f.attack={type,t:0,hit:false};f.cool=type==='punch'?.42:type==='kick'?.65:.95;sound(type==='special'?250:130,.09)}
function press(k){keys[k]=true;if(k==='p'||k==='escape')pause();if(k==='j')attack(p,'punch');if(k==='k')attack(p,'kick');if(k==='l')attack(p,'special');if(k==='b')transform(p);if(k==='w'&&state==='fight'&&p.y===0&&p.stun<=0)p.vy=650}
window.addEventListener('keydown',ev=>{if(ev.target.matches('input,select'))return;let k=ev.key.toLowerCase();k=({arrowleft:'a',arrowright:'d',arrowup:'w',arrowdown:'s'})[k]||k;if(['a','d','w','s','j','k','l','b','p','escape',' '].includes(k))ev.preventDefault();if(!ev.repeat)press(k)});window.addEventListener('keyup',ev=>{const k=({arrowleft:'a',arrowright:'d',arrowup:'w',arrowdown:'s'})[ev.key.toLowerCase()]||ev.key.toLowerCase();keys[k]=false});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=ev=>{ev.preventDefault();b.setPointerCapture(ev.pointerId);press(b.dataset.key)};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false;b.onlostpointercapture=()=>keys[b.dataset.key]=false}
window.addEventListener('blur',()=>{keys={};if(['fight','countdown','roundover'].includes(state))pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMusic();keys={};if(['fight','countdown','roundover'].includes(state))pause()}});
function hit(f,target){const a=f.attack,range=a.type==='punch'?135:a.type==='kick'?185:255;if(Math.abs(f.x-target.x)>range||Math.abs(f.y-target.y)>105||(target.x-f.x)*f.face<0)return;const blocked=target.block&&target.y===0;let damage=a.type==='punch'?9:a.type==='kick'?15:28;damage*= (.7+f.data.power*.045)*(f.beast>0?1.25:1)*(1.15-target.data.guard*.025);if(blocked)damage*=.18;f.rage=clamp(f.rage+12,0,100);target.rage=clamp(target.rage+16,0,100);target.hp=Math.max(0,target.hp-damage);target.stun=blocked?.08:.23;target.x=clamp(target.x+f.face*(blocked?8:22),70,1210);f.energy=clamp(f.energy+15,0,100);target.energy=clamp(target.energy+8,0,100);shake=blocked?2:9;sound(blocked?80:180,.15);for(let i=0;i<20;i++)particles.push({x:target.x-f.face*30,y:545-target.y,vx:(Math.random()-.5)*600,vy:(Math.random()-.6)*500,life:.25+Math.random()*.2,color:blocked?'#9adfff':f.color});}
function updateFighter(f,target,dt,move){f.beast=Math.max(0,f.beast-dt);f.face=target.x>=f.x?1:-1;f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);if(f.stun<=0&&!f.attack&&!f.block){f.x=clamp(f.x+move*(170+f.data.speed*13)*(f.beast>0?1.15:1)*dt,70,1210);f.walk+=Math.abs(move)*dt*12}else f.walk=0;f.vy-=1700*dt;f.y=Math.max(0,f.y+f.vy*dt);if(!f.y)f.vy=0;if(f.attack){f.attack.t+=dt;const a=f.attack,impact=a.type==='punch'?.12:.22,duration=a.type==='punch'?.3:.48;if(a.t>=impact&&!a.hit){a.hit=true;hit(f,target)}if(a.t>duration)f.attack=null}}
function endRound(){if(state!=='fight')return;const win=p.hp===e.hp?-1:p.hp>e.hp?0:1;if(win>=0)wins[win]++;state='roundover';transition=2.4;$('announce').textContent=win===-1?'EMPATE':win===0?'ROUND GANADO':'ROUND PERDIDO';sound(win===0?500:90,.3)}
function finish(){state='over';$('modal').hidden=false;$('announce').textContent='';const won=wins[0]===2;storyWon=won;if(won)storage.set('rift.wins.'+name.toLowerCase(),String(record()+1));$('result-label').textContent=(storyMode?'HISTORIA · CAPÍTULO '+(chapter+1):'DUELO LIBRE')+' / '+wins[0]+' — '+wins[1];$('result-title').textContent=won?(storyMode&&chapter===2?'Un nuevo comienzo.':'La arena es tuya.'):'Vuelve más fuerte.';$('result-copy').textContent=won?(storyMode&&chapter===2?roster[selected].ending:storyMode?'Has vencido a '+roster[opponent].name+'. La siguiente pista te acerca al origen de Génesis.':'Victoria de '+roster[selected].name+'. Has dominado el instinto del '+roster[selected].animal.toLowerCase()+'.'):'Observa la distancia, bloquea y usa B para liberar tu forma bestial. Tu historia todavía no termina.';$('resume').textContent=storyMode&&won?(chapter<2?'SIGUIENTE CAPÍTULO →':'ELEGIR OTRO LUCHADOR →'):'REVANCHA →';if(storyMode&&won&&chapter===2){storage.set('rift.ending.'+name.toLowerCase()+'.'+roster[selected].id,'1');$('modal').querySelector('.result').classList.add('story-result')}}

